/**
 * issue #98: production Activity-side #89 suspension adapter for the one
 * project-owned "temporal signal wait" node (`lib/nodes/signal-wait.js`).
 *
 * This promotes only the GENERIC semantics already proven by #91's
 * test-only fixture (`test/.../fixtures/signalSuspensionAdapter.js`) into
 * project-owned runtime code, narrowed from "any node whose msg carries
 * `waitKey`" to "only this one node type" - a real flow author's ordinary
 * `change`/`debug`/etc. nodes must never accidentally suspend just because
 * an upstream node happened to leave a `waitKey`-named property on the
 * msg.
 *
 * `plan(node, msg)`:
 *   - returns `undefined` (do not suspend) for every node type except
 *     `"temporal signal wait"` - the ONLY node-type check in this file,
 *     and it never leaks into `workflows.js` (issue's hard constraint);
 *   - resolves the correlation key by reading `msg[node.keyProperty]`
 *     (default msg property name: `waitKey`, configured in the editor -
 *     see `lib/nodes/signal-wait.html`). No expression language - a plain
 *     msg property lookup only;
 *   - requires the resolved key to be a non-empty string; anything else
 *     (missing, empty, non-string) is treated as a configuration/runtime
 *     error and surfaces as an ordinary Activity error rather than an
 *     unexplained silent pass-through, so a misconfigured flow fails
 *     loudly instead of quietly never suspending;
 *   - returns `{type: "signal", key, continuation: null}` - no extra
 *     plan-time state needed, `resume()` gets the ORIGINAL `msg` back
 *     unchanged (per `workflows.js`'s `scheduleSuspension`), and the live
 *     node instance passed to `resume()` still carries the same
 *     `keyProperty` config.
 *
 * `resume(node, msg, resumeInput)`:
 *   - treats `resumeInput.signal` as fully opaque (never inspects its
 *     shape) and exposes it to the resumed message via exactly one
 *     documented property: `msg.signal`;
 *   - removes the configured `keyProperty` from the resumed msg before
 *     sending it on. This node's `plan()` only ever suspends invocations
 *     of THIS node type, so an ordinary downstream node reusing the same
 *     msg object is never at risk of accidental re-suspension by this
 *     adapter regardless - but a flow author wiring a Signal Wait node's
 *     output back into ANOTHER Signal Wait node with the SAME
 *     `keyProperty` name (already-consumed key) would otherwise appear to
 *     durably (and forever) suspend again on a key nothing will ever
 *     re-signal. Stripping the property removes that foot-gun the same
 *     way #90/#91 already do for their own suspending nodes;
 *   - sends via `capture.routeSend()` (capture.js), so the resolved
 *     `destinationId` always comes from Node-RED's own `preRoute` hook,
 *     never a raw wire-graph lookup - matching #90/#91's routing
 *     guarantee.
 *
 * Does NOT duplicate `workflows.js`'s consume-once keyed-Signal-inbox
 * logic (#91's `condition()`/inbox bookkeeping) - this file only ever
 * decides WHETHER/WHAT to suspend and how to interpret a delivered
 * signal's payload; the Workflow alone owns correlation-key bookkeeping,
 * wake-one-waiter semantics, and duplicate/unrelated-signal handling.
 */

"use strict";

const NODE_TYPE = "temporal signal wait";
const DEFAULT_KEY_PROPERTY = "waitKey";

function resolveKeyProperty(node) {
    return (node && typeof node.keyProperty === "string" && node.keyProperty.length > 0)
        ? node.keyProperty
        : DEFAULT_KEY_PROPERTY;
}

function createSignalSuspensionAdapter({ capture }) {
    function plan(node, msg) {
        if (!node || node.type !== NODE_TYPE) {
            return undefined;
        }
        const keyProperty = resolveKeyProperty(node);
        const key = msg ? msg[keyProperty] : undefined;
        if (typeof key !== "string" || key.length === 0) {
            throw new Error(`temporal signal wait node ${node.id}: msg.${keyProperty} must be a non-empty string`);
        }
        return { type: "signal", key: key, continuation: null };
    }

    async function resume(node, msg, resumeInput) {
        const keyProperty = resolveKeyProperty(node);
        const resumedMsg = Object.assign({}, msg, { signal: resumeInput.signal });
        delete resumedMsg[keyProperty];
        const routed = capture.routeSend(node, resumedMsg, function() {
            node.send(resumedMsg);
        });
        return { sends: routed.sends };
    }

    return { plan, resume };
}

module.exports = { createSignalSuspensionAdapter, NODE_TYPE, DEFAULT_KEY_PROPERTY };
